@section('heading','Abrir chamado')
@section('content')<div class="mb-4"><div class="eyebrow">Nova ocorrência</div><h2 class="h3">Conte o que precisa de atenção.</h2><p class="text-secondary">A equipe receberá o chamado com o local e a prioridade informados.</p></div><form id="chamado-form" class="panel p-4 p-lg-5" enctype="multipart/form-data"><div class="row g-4"><div class="col-lg-8"><label class="form-label">Título</label><input class="form-control form-control-lg" name="titulo" required maxlength="160"><label class="form-label mt-3">Descrição</label><textarea class="form-control" name="descricao" rows="7" required></textarea></div><div class="col-lg-4"><label class="form-label">Local</label><select class="form-select" name="local_id" id="local" required></select><label class="form-label mt-3">Categoria</label><select class="form-select" name="categoria_id" id="categoria" required></select><label class="form-label mt-3">Prioridade</label><select class="form-select" name="prioridade_id" id="prioridade" required></select><label class="form-label mt-3">Foto (opcional)</label><input class="form-control" type="file" name="foto" accept="image/*"></div></div><div class="d-flex justify-content-end gap-2 mt-4"><a href="{{ route('dashboard') }}" class="btn btn-light">Cancelar</a><button class="btn btn-primary">Salvar chamado</button></div></form>@endsection
@section('scripts')<script>$(function(){let token=@json(session('api_token'));$.ajax({url:'/api/catalogos',headers:{Authorization:'Bearer '+token}}).done(function(d){[['#local',d.locais],['#categoria',d.categorias],['#prioridade',d.prioridades]].forEach(function(pair){pair[1].forEach(x=>$(pair[0]).append(new Option(x.nome,x.id)))})});$('#chamado-form').on('submit',function(e){e.preventDefault();$.ajax({url:'/api/chamados',method:'POST',data:new FormData(this),processData:false,contentType:false,headers:{Authorization:'Bearer '+token}}).done(function(){Swal.fire('Chamado salvo','Sua ocorrência foi registrada.','success').then(()=>location.href='{{ route('chamados.mine') }}')}).fail(function(xhr){Swal.fire('Revise os dados',Object.values(xhr.responseJSON?.errors||{}).flat().join('<br>')||'Não foi possível salvar.','error')})})});</script>@endsection